{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "In guinea-pigs, the cardiac glycoside SC-4453 showed the lowest tissue concentration in brain at steady state, demonstrating a blood-brain barrier to this glycoside; this transfers to the query's glycosidic anthracycline scaffold and supports poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Mithramycin, a polyglycosylated anthracycline-like natural product, achieved only a 0.12 CSF:plasma ratio in monkeys with little material in normal brains, directly indicating poor CNS penetration for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "DIFEQ, a polyphenolic glycoside, showed very low brain uptake (0.003% of injected dose) in mice and was characterized as poor penetration, supporting the fail prediction for the query's polar glycoside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Digitoxin showed very low CSF/plasma ratios (0.01-0.03) in dogs, indicating that large glycosides do not easily penetrate the blood-brain barrier; the query's anthracycline glycoside is similarly large and efflux-prone.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is daunorubicin, an anthracycline glycoside with an aminosugar and multiple polar hydroxyls. Multiple high-transfer direct measurements on glycosylated/anthracycline-like molecules show very low brain uptake, low CSF:plasma ratios, and brain as the lowest-distribution tissue. These consistent experimental phenotypes indicate inadequate CNS access after systemic administration.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for daunorubicin itself in the supplied evidence.",
    "No P-gp/BCRP transporter inhibition data for the query.",
    "Most evidence is from rodent or non-human species; human data are limited to a macrolide analogue."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

